package rules

import (
	"strings"
	"testing"
)

func TestReportMarkdown(t *testing.T) {
	t.Parallel()
	report := analyzeFixture(t, "bad.md")
	exported := ReportMarkdown(report)
	for _, want := range []string{
		"# README check: owner/demo",
		"https://github.com/owner/demo",
		"**Score:**",
		"## Category scores",
		"## Checklist",
		"### Getting started",
		"**FAIL** — `installation-section`",
		"**Why it matters:**",
		"**How to fix:**",
		"Generated by readmecheck",
	} {
		if !strings.Contains(exported, want) {
			t.Errorf("export does not contain %q\n%s", want, exported)
		}
	}
	if strings.Contains(exported, "**PASS** — `installation-section`") {
		t.Error("failed installation rule marked as pass")
	}
}

func TestReportMarkdownWithoutRepository(t *testing.T) {
	t.Parallel()
	report := Report{}
	exported := ReportMarkdown(report)
	if !strings.Contains(exported, "# README check: repository") {
		t.Fatalf("unexpected export:\n%s", exported)
	}
}
